/// The extension IEs of `SecurityIndication-ExtIEs` (NGAP-IEs). IEs not defined here are kept in `unknown_ies`.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct SecurityIndicationExtIes {
    /// `id-MaximumIntegrityProtectedDataRate-DL` (id 151, Ignore, Optional)
    pub maximum_integrity_protected_data_rate_dl: Option<MaximumIntegrityProtectedDataRate>,
    /// IEs this version of the specification does not define here, as received (id, criticality, encoded value).
    pub unknown_ies: Vec<rt::ie::RawIe>,
}

impl SecurityIndicationExtIes {
    /// A value with the mandatory IEs given and every optional one absent.
    pub fn new() -> Self {
        Self {
            maximum_integrity_protected_data_rate_dl: None,
            unknown_ies: Vec::new(),
        }
    }
}

impl rt::AperEncode for SecurityIndicationExtIes {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        let mut ies: Vec<rt::ie::RawIe> = Vec::new();
        if let Some(x) = &self.maximum_integrity_protected_data_rate_dl {
            ies.push(rt::ie::RawIe::new(151, rt::ie::Criticality::Ignore, x)?);
        }
        ies.extend(self.unknown_ies.iter().cloned());
        rt::ie::write_container(w, rt::Size::range(1, 65535), &ies)
    }
}

impl rt::AperDecode for SecurityIndicationExtIes {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let mut s_maximum_integrity_protected_data_rate_dl: Option<MaximumIntegrityProtectedDataRate> = None;
        let mut unknown_ies = Vec::new();
        for ie in rt::ie::read_container(r, rt::Size::range(1, 65535))? {
            match ie.id {
                151 => rt::ie::set_once(&mut s_maximum_integrity_protected_data_rate_dl, 151, ie.decode()?)?,
                _ => {
                    rt::ie::note_unknown(&ie);
                    unknown_ies.push(ie)
                }
            }
        }
        Ok(Self {
            maximum_integrity_protected_data_rate_dl: s_maximum_integrity_protected_data_rate_dl,
            unknown_ies,
        })
    }
}

