/// ASN.1 `SensorNameConfig` (NGAP-IEs).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SensorNameConfig {
    /// `uncompensatedBarometricConfig`
    UncompensatedBarometricConfig(SensorNameConfigUncompensatedBarometricConfig),
    /// `ueSpeedConfig`
    UeSpeedConfig(SensorNameConfigUeSpeedConfig),
    /// `ueOrientationConfig`
    UeOrientationConfig(SensorNameConfigUeOrientationConfig),
    /// `choice-Extensions`
    ChoiceExtensions(rt::ie::RawIe),
}

impl rt::AperEncode for SensorNameConfig {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        match self {
            Self::UncompensatedBarometricConfig(x) => {
                w.write_index(0, 4, false)?;
                x.aper_encode(w)
            }
            Self::UeSpeedConfig(x) => {
                w.write_index(1, 4, false)?;
                x.aper_encode(w)
            }
            Self::UeOrientationConfig(x) => {
                w.write_index(2, 4, false)?;
                x.aper_encode(w)
            }
            Self::ChoiceExtensions(x) => {
                w.write_index(3, 4, false)?;
                x.aper_encode(w)
            }
        }
    }
}

impl rt::AperDecode for SensorNameConfig {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        match r.read_index(4, false)? {
            0 => Ok(Self::UncompensatedBarometricConfig(<SensorNameConfigUncompensatedBarometricConfig>::aper_decode(r)?)),
            1 => Ok(Self::UeSpeedConfig(<SensorNameConfigUeSpeedConfig>::aper_decode(r)?)),
            2 => Ok(Self::UeOrientationConfig(<SensorNameConfigUeOrientationConfig>::aper_decode(r)?)),
            3 => Ok(Self::ChoiceExtensions(<rt::ie::RawIe>::aper_decode(r)?)),
            i => Err(r.error(rt::ErrorKind::InvalidIndex(i))),
        }
    }
}

