impl rt::AperEncode for ServedGuamiItem {
    fn aper_encode(&self, w: &mut rt::BitWriter) -> rt::Result<()> {
        w.write_bit(false); // extension marker: no additions
        w.write_bit(self.backup_amf_name.is_some());
        w.write_bit(self.ie_extensions.is_some());
        {
            let x = &self.guami;
            x.aper_encode(w)?;
        }
        if let Some(x) = &self.backup_amf_name {
            x.aper_encode(w)?;
        }
        if let Some(x) = &self.ie_extensions {
            x.aper_encode(w)?;
        }
        Ok(())
    }
}

impl rt::AperDecode for ServedGuamiItem {
    fn aper_decode(r: &mut rt::BitReader<'_>) -> rt::Result<Self> {
        let extension = r.read_bit()?;
        let p_backup_amf_name = r.read_bit()?;
        let p_ie_extensions = r.read_bit()?;
        let v_guami = <Guami>::aper_decode(r)?;
        let v_backup_amf_name = if p_backup_amf_name { Some(<AmfName>::aper_decode(r)?) } else { None };
        let v_ie_extensions = if p_ie_extensions { Some(<ServedGuamiItemExtIes>::aper_decode(r)?) } else { None };
        if extension {
            r.read_extension_additions()?;
        }
        Ok(Self {
            guami: v_guami,
            backup_amf_name: v_backup_amf_name,
            ie_extensions: v_ie_extensions,
        })
    }
}

